CREATE TABLE Attendance (
  person_id STRING(36) NOT NULL,
  event_id STRING(36) NOT NULL,
  attendance_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
) PRIMARY KEY(person_id, event_id);

CREATE INDEX AttendanceByEvent ON Attendance(event_id, person_id);

CREATE TABLE Event (
  event_id STRING(36) NOT NULL,
  name STRING(MAX),
  description STRING(MAX),
  event_date TIMESTAMP,
  create_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
) PRIMARY KEY(event_id);

CREATE INDEX EventByDate ON Event(event_date DESC);

CREATE TABLE EventLocation (
  event_id STRING(36) NOT NULL,
  location_id STRING(36) NOT NULL,
  create_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
  CONSTRAINT FK_Event FOREIGN KEY(event_id) REFERENCES Event(event_id),
) PRIMARY KEY(event_id, location_id);

CREATE INDEX EventLocationByLocationId ON EventLocation(location_id, event_id);

CREATE TABLE Friendship (
  person_id_a STRING(36) NOT NULL,
  person_id_b STRING(36) NOT NULL,
  friendship_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
) PRIMARY KEY(person_id_a, person_id_b);

CREATE INDEX FriendshipByPersonB ON Friendship(person_id_b, person_id_a);

CREATE TABLE Location (
  location_id STRING(36) NOT NULL,
  name STRING(MAX),
  description STRING(MAX),
  latitude FLOAT64,
  longitude FLOAT64,
  address STRING(MAX),
  create_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
) PRIMARY KEY(location_id);

ALTER TABLE EventLocation ADD CONSTRAINT FK_Location FOREIGN KEY(location_id) REFERENCES Location(location_id);

CREATE TABLE Mention (
  post_id STRING(36) NOT NULL,
  mentioned_person_id STRING(36) NOT NULL,
  mention_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
) PRIMARY KEY(post_id, mentioned_person_id);

CREATE INDEX MentionByPerson ON Mention(mentioned_person_id, post_id);

CREATE TABLE Person (
  person_id STRING(36) NOT NULL,
  name STRING(MAX),
  age INT64,
  create_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
) PRIMARY KEY(person_id);

CREATE INDEX PersonByName ON Person(name);

CREATE TABLE Post (
  post_id STRING(36) NOT NULL,
  author_id STRING(36) NOT NULL,
  text STRING(MAX),
  sentiment STRING(50),
  post_timestamp TIMESTAMP,
  create_time TIMESTAMP NOT NULL OPTIONS (
    allow_commit_timestamp = true
  ),
) PRIMARY KEY(post_id);

CREATE INDEX PostByAuthor ON Post(author_id, post_timestamp DESC);

CREATE INDEX PostByTimestamp ON Post(post_timestamp DESC);

CREATE PROPERTY GRAPH IF NOT EXISTS SocialGraph
  NODE TABLES(
    Event
      KEY(event_id)
      LABEL Event PROPERTIES(
        create_time,
        description,

